@@ -0,0 +1,48 @@
+package hotel.reservations;
+
+import hotel.rooms.Room;
+import java.math.BigDecimal;
+import java.time.LocalDate;
+import java.time.Month;
+
+final class StandardPricing implements RatePlanPricing {
+
+    private static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
+
+    @Override
+    public void validate(NewReservation request, Room room) {
+    }
+
+    @Override
+    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
+        int nights = 0;
+        BigDecimal subtotal = PriceCalculator.cents(BigDecimal.ZERO);
+        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
+            subtotal = subtotal.add(nightPrice(room, night));
+            nights++;
+        }
+        BigDecimal discount = PriceCalculator.cents(BigDecimal.ZERO);
+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
+    }
+
+    @Override
+    public BigDecimal calculateRefund(BigDecimal amountPaid) {
+        return amountPaid;
+    }
+
+    static BigDecimal nightPrice(Room room, LocalDate night) {
+        BigDecimal nightlyRate = room.nightlyRate();
+        if (isHighSeason(night)) {
+            return PriceCalculator.cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
+        }
+        return PriceCalculator.cents(nightlyRate);
+    }
+
+    static boolean isHighSeason(LocalDate date) {
+        Month month = date.getMonth();
+        return month == Month.JANUARY
+                || month == Month.FEBRUARY
+                || month == Month.JULY
+                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
+    }
+}
diff --git a/src/main/java/hotel/reservations/WeekendPackagePricing.java b/src/main/java/hotel/reservations/WeekendPackagePricing.java
new file mode 100644
index 0000000..1e33322
--- /dev/null
+++ b/src/main/java/hotel/reservations/WeekendPackagePricing.java
@@ -0,0 +1,44 @@
+package hotel.reservations;
+
+import hotel.rooms.Room;
+import hotel.rooms.RoomType;
+import java.math.BigDecimal;
+import java.time.DayOfWeek;
+import java.time.LocalDate;
+import java.util.Map;
+
+final class WeekendPackagePricing implements RatePlanPricing {
+
+    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
+            RoomType.STANDARD, new BigDecimal("520.00"),
+            RoomType.DELUXE, new BigDecimal("820.00"),
+            RoomType.SUITE, new BigDecimal("1200.00"));
+
+    @Override
+    public void validate(NewReservation request, Room room) {
+        if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package must start on a Friday");
+        }
+        if (request.checkOut().getDayOfWeek() != DayOfWeek.SUNDAY) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package must end on a Sunday");
+        }
+        long nights = java.time.temporal.ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
+        if (nights != 2) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST, "weekend package must be exactly 2 nights");
+        }
+    }
+
+    @Override
+    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
+        BigDecimal packagePrice = PACKAGE_PRICES.get(room.type());
+        return new Price(2, packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
+    }
+
+    @Override
+    public BigDecimal calculateRefund(BigDecimal amountPaid) {
+        return PriceCalculator.cents(amountPaid.divide(new BigDecimal("2")));
+    }
+}
